const stageBeforeHierarchyVideos=stage;
stage=function(){if(tab!==4||!data.shotScript?.hierarchical){stageBeforeHierarchyVideos();return;}const panel=document.querySelector('#panel');let grid=panel.querySelector('#hierarchyVideoGrid');if(!grid||grid.dataset.projectId!==data.project_id){panel.innerHTML='<div class="section-head"><div><h3>主分镜视频</h3><p>一个主分镜对应一次视频生成，子分镜是片段内部时间轴。</p></div></div><div id="hierarchyVideoGrid" class="shot-reference-grid"></div>';grid=panel.querySelector('#hierarchyVideoGrid');grid.dataset.projectId=data.project_id;}
const cards=new Map([...grid.children].map(card=>[card.dataset.videoShotId,card])),ids=new Set();
for(const [i,s]of data.shots.entries()){const id=s.shot_id||s.id;ids.add(id);let card=cards.get(id);if(!card){card=document.createElement('div');card.className='card';card.dataset.videoShotId=id;card.innerHTML='<b data-video-title></b><p class="subtle" data-video-meta></p><div data-video-slot></div><p class="subtle" data-video-message></p><button data-main-video="'+i+'">进入主分镜生成</button>';}
card.querySelector('[data-video-title]').textContent=id+' · '+(s.title||'');card.querySelector('[data-video-meta]').textContent=s.sub_shots.length+' 个子分镜 · '+s.duration+' 秒';const open=card.querySelector('[data-main-video]');open.dataset.mainVideo=String(i);open.onclick=()=>{si=data.shots.findIndex(x=>(x.shot_id||x.id)===id);selectedSubShot=0;shotMode='shots';tab=2;render();};
const version=selectedShotVideo(s),slot=card.querySelector('[data-video-slot]'),message=card.querySelector('[data-video-message]');let player=slot.querySelector('video');const playing=player&&!player.paused&&!player.ended;const desired=version?.video_url||'';
if(desired){if(!player){player=document.createElement('video');player.controls=true;player.preload='metadata';player.style.width='100%';player.addEventListener('ended',()=>{if(tab===4)stage();});slot.append(player);}if(player.getAttribute('src')!==desired){if(playing){message.textContent='新版本已生成，当前播放结束后更新';}else{player.src=desired;message.textContent='';}}else message.textContent='';}
else{if(player){player.pause();player.remove();}message.textContent=s.videoJob?'任务状态：'+s.videoJob.status:'尚未生成新版视频';}
const remove=card.querySelector('[data-delete-shot-video]');if(remove)remove.disabled=videoBusy(s.videoJob);if(grid.children[i]!==card)grid.insertBefore(card,grid.children[i]||null);}
for(const [id,card]of cards)if(!ids.has(id)){card.querySelector('video')?.pause();card.remove();}
};
const hierarchicalShotsWithVideo=shots;shots=function(){hierarchicalShotsWithVideo();if(data.shotScript?.hierarchical){const button=document.querySelector('#shotVideoGenerate');if(button&&!videoBusy(shotVideoTarget()?.videoJob))button.textContent=(selectedShotVideo(shotVideoTarget())?'重新生成 ':'生成 ')+(shotVideoTarget()?.shot_id||'')+' · 完整分镜视频';const label=document.querySelector('#shotVideoPanel .preview-head b');if(label)label.textContent='完整主分镜视频 · MiniMax H3';}};render();